# Demo: bg=4, line color=1, marker=2. Rule: full lines of non-bg color -> marker.
def fg(g,bg=None,mk=2):
    n,m=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    ret=[row[:] for row in g]
